hero_css:
.eh-home .eh-hero-carousel{position:relative;min-height:640px;padding:0;background:#071f32;overflow:hidden;color:#fff}
.eh-hero-carousel .eh-carousel-slides,.eh-hero-carousel .eh-hero-slide{position:absolute;inset:0}
.eh-hero-carousel .eh-hero-slide{opacity:0;visibility:hidden;transition:opacity .8s ease,visibility .8s ease}
.eh-hero-carousel .eh-hero-slide.is-active{opacity:1;visibility:visible;z-index:1}
.eh-hero-carousel .eh-slide-image{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center}
.eh-hero-carousel .eh-slide-shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(4,22,37,.91) 0%,rgba(5,29,47,.78) 44%,rgba(5,29,47,.18) 100%),linear-gradient(0deg,rgba(4,22,37,.42),transparent 45%)}
.eh-hero-carousel .eh-slide-container{position:relative;z-index:2;display:flex;align-items:center;min-height:640px;padding-top:75px;padding-bottom:100px}
.eh-hero-carousel .eh-slide-copy{max-width:670px;padding:30px 0;color:#fff}
.eh-hero-carousel .eh-eyebrow{color:#c8e9ff}
.eh-hero-carousel .eh-eyebrow-dot{background:#63c2f5;box-shadow:0 0 0 5px #63c2f533}
.eh-hero-carousel .eh-slide-overline{display:block;margin-top:35px;color:#80cfff;font-size:11px;font-weight:850;letter-spacing:2.5px}
.eh-hero-carousel h1{margin:16px 0 20px;color:#fff;font-size:clamp(43px,6vw,76px);line-height:1.03;font-weight:850;letter-spacing:-2.8px}
.eh-hero-carousel h1 span{color:#76caff}
.eh-hero-carousel .eh-hero-copy{max-width:570px;color:#e0eaf1;font-size:16px;line-height:1.85}
.eh-hero-carousel .eh-hero-actions{margin-top:28px}
.eh-hero-carousel .eh-btn-primary{background:#1686ca;box-shadow:0 12px 28px #001a2c55}
.eh-hero-carousel .eh-btn-primary:hover{background:#0870b2}
.eh-hero-carousel .eh-btn-outline{border-color:#ffffff80;background:#ffffff12;color:#fff!important;backdrop-filter:blur(8px)}
.eh-hero-carousel .eh-carousel-controls{position:absolute;z-index:3;left:50%;bottom:28px;display:flex;align-items:center;gap:22px;transform:translateX(-50%)}
.eh-carousel-pagination{display:flex;align-items:center;gap:9px}
.eh-carousel-dot{width:9px;height:9px;padding:0;border:0;border-radius:50%;background:#ffffff80;cursor:pointer;transition:width .25s,background .25s}
.eh-carousel-dot.is-active{width:29px;border-radius:10px;background:#72caff}
.eh-carousel-arrows{display:flex;gap:8px;margin-left:auto}
.eh-carousel-arrows button{display:grid;place-items:center;width:38px;height:38px;border:1px solid #ffffff70;border-radius:50%;background:#ffffff12;color:#fff;font-size:18px;cursor:pointer;transition:background .2s}
.eh-carousel-arrows button:hover{background:#1686ca;border-color:#1686ca}
.eh-carousel-note{color:#d2e3ee;font-size:9px;font-weight:850;letter-spacing:1.7px;white-space:nowrap}
.eh-carousel-note i{padding:0 5px;color:#76caff;font-style:normal}
.eh-hero-carousel button:focus-visible,.eh-hero-carousel a:focus-visible{outline:3px solid #8bd4ff;outline-offset:4px}
@media(max-width:767.98px){.eh-home .eh-hero-carousel{min-height:610px}.eh-hero-carousel .eh-slide-container{min-height:610px;padding-top:52px;padding-bottom:105px}.eh-hero-carousel .eh-slide-shade{background:linear-gradient(90deg,rgba(4,22,37,.88),rgba(5,29,47,.55)),linear-gradient(0deg,rgba(4,22,37,.5),transparent 65%)}.eh-hero-carousel .eh-slide-copy{padding:20px 0}.eh-hero-carousel .eh-slide-overline{margin-top:27px}.eh-hero-carousel h1{font-size:clamp(40px,10vw,58px);letter-spacing:-1.7px}.eh-hero-carousel .eh-hero-copy{font-size:14px;line-height:1.75}.eh-hero-carousel .eh-carousel-controls{bottom:22px;gap:14px}.eh-carousel-note{display:none}.eh-carousel-arrows{margin-left:auto}}
@media(max-width:420px){.eh-home .eh-hero-carousel{min-height:590px}.eh-hero-carousel .eh-slide-container{min-height:590px}.eh-hero-carousel .eh-hero-actions{flex-direction:column;align-items:stretch}.eh-hero-carousel .eh-hero-actions .eh-btn{width:100%}}
@media(prefers-reduced-motion:reduce){.eh-hero-carousel .eh-hero-slide,.eh-carousel-dot,.eh-carousel-arrows button{transition:none}}

