document.addEventListener("DOMContentLoaded", function () {
  document.querySelectorAll(".eh-home a[href='#']").forEach(function (link) {
    link.addEventListener("click", function (event) { event.preventDefault(); });
  });

  var carousel = document.querySelector(".eh-hero-carousel");
  if (!carousel) return;
  var slides = Array.prototype.slice.call(carousel.querySelectorAll(".eh-hero-slide"));
  var dots = Array.prototype.slice.call(carousel.querySelectorAll(".eh-carousel-dot"));
  var current = 0;
  var timer = null;
  var reducedMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function showSlide(index) {
    current = (index + slides.length) % slides.length;
    slides.forEach(function (slide, i) {
      var active = i === current;
      slide.classList.toggle("is-active", active);
      slide.setAttribute("aria-hidden", active ? "false" : "true");
    });
    dots.forEach(function (dot, i) {
      var active = i === current;
      dot.classList.toggle("is-active", active);
      if (active) dot.setAttribute("aria-current", "true");
      else dot.removeAttribute("aria-current");
    });
  }
  function stopTimer() { if (timer) window.clearInterval(timer); timer = null; }
  function startTimer() {
    stopTimer();
    if (!reducedMotion && !document.hidden) timer = window.setInterval(function () { showSlide(current + 1); }, 6500);
  }

  dots.forEach(function (dot) {
    dot.addEventListener("click", function () {
      showSlide(parseInt(dot.getAttribute("data-slide"), 10));
      startTimer();
    });
  });
  var previous = carousel.querySelector(".eh-carousel-prev");
  var next = carousel.querySelector(".eh-carousel-next");
  if (previous) previous.addEventListener("click", function () { showSlide(current - 1); startTimer(); });
  if (next) next.addEventListener("click", function () { showSlide(current + 1); startTimer(); });
  carousel.addEventListener("mouseenter", stopTimer);
  carousel.addEventListener("mouseleave", startTimer);
  carousel.addEventListener("focusin", stopTimer);
  carousel.addEventListener("focusout", function (event) {
    if (!carousel.contains(event.relatedTarget)) startTimer();
  });
  document.addEventListener("visibilitychange", function () {
    if (document.hidden) stopTimer(); else startTimer();
  });
  showSlide(0);
  startTimer();
});
